{
  "constraints": [
    {
      "constraint": "图像应表现宁波的城市轨道交通/地铁系统，而非泛指其他交通系统；画面中至少包含一种可识别的地铁或轨道交通要素。",
      "polarity": "must_have",
      "variants": [
        "地铁/轨道交通列车",
        "地铁/轨道交通轨道",
        "地铁/轨道交通车站或站台",
        "宁波轨道交通线路图",
        "宁波轨道交通标识"
      ],
      "source": "common_sense"
    },
    {
      "constraint": "图像应包含至少一个可识别为宁波的地域指向元素，使其区别于其他城市的地铁系统。",
      "polarity": "must_have",
      "variants": [
        "宁波或宁波轨道交通文字标识",
        "宁波轨道交通线路图或站名",
        "宁波城市地标",
        "宁波轨道交通标志"
      ],
      "source": "common_sense"
    },
    {
      "constraint": "图像不得以普通道路交通场景或道路交通工具（如公交车、私家车、出租车、自行车等）作为主体。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "图像不得以航空器或船舶作为主体。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "图像不得以国家铁路、高铁动车组或火车站作为主体。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    }
  ]
}
